# Pydantic has `Discriminator`. 

# Let's try to use the exact code from the problem statement.
# I will define Tag and Discriminator as simple classes if they are not found.

class Tag:
    def __init__(self, value):
        self.value = value

class Discriminator:
    def __init__(self, func):
        self.func = func

Dessert = Annotated[
    Annotated[ApplePie, Tag("apple")] | Annotated[PumpkinPie, Tag("pumpkin")],
    Discriminator(get_discriminator_value),
]

app = FastAPI()
@app.post("/dessert")
async def dinner(dessert: Dessert) -> dict[str, Any]:
    return dessert.model_dump()

client = TestClient(app)

def test_dessert():
    # This should be a body parameter
    response = client.post("/dessert", json={"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5})
    assert response.status_code == 200
    assert response.json() == {"fruit": "apple", "time_to_cook": 30, "num_ingredients": 5}

    response = client.post("/dessert", json={"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10})
    assert response.status_code == 200
    assert response.json() == {"filling": "pumpkin", "time_to_cook": 60, "num_ingredients": 10}

if __name__ == "__main__":
    try:
        test_dessert()
        print("Test passed!")
    except Exception as e:
